create or replace function public.record_favorite_route_event(p_location_id uuid, p_user_id uuid default null, p_from_lat numeric default null, p_from_lng numeric default null) returns uuid language plpgsql security definer set search_path = public, auth, extensions, pg_temp as $$ declare v_id uuid; v_user uuid := auth.uid(); begin if v_user is null then raise exception 'Authentication required'; end if; insert into public.location_route_events(location_id,user_id,source,from_lat,from_lng) values(p_location_id,v_user,'favorite',p_from_lat,p_from_lng) returning id into v_id; return v_id; end; $$;

create or replace function public.record_location_route_event(p_location_id uuid, p_from_favorite boolean default false) returns void language plpgsql security definer set search_path = public, auth, extensions, pg_temp as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; insert into public.location_route_events(user_id,location_id,from_favorite) values(auth.uid(),p_location_id,p_from_favorite); end; $$;

create or replace function public.populate_route_discovery_cache(p_session_id uuid, p_route_geometry jsonb default null) returns jsonb language plpgsql set search_path = public as $$ declare v_user uuid:=auth.uid(); v_session public.route_discovery_sessions; v_geometry jsonb; v_inserted integer:=0; begin if v_user is null then raise exception 'Authentication required'; end if; select * into v_session from public.route_discovery_sessions where id=p_session_id and user_id=v_user for update; if not found then raise exception 'Route discovery session not found'; end if; v_geometry:=coalesce(p_route_geometry,v_session.route_geometry); if v_geometry is null then raise exception 'Route geometry is required to prepare corridor discovery'; end if; update public.route_discovery_sessions set route_geometry=v_geometry,status='discovering',updated_at=now() where id=p_session_id; insert into public.route_discovery_locations(session_id,location_id,trigger_radius_meters,source,discovered_at,geofence_enabled) select p_session_id,l.id,greatest(100,least(1000,coalesce(l.geofence_radius_m,300))),'supabase_cache',now(),true from public.locations l where l.is_active=true and l.geom is not null and ST_DWithin(l.geom,ST_SetSRID(ST_GeomFromGeoJSON(v_geometry::text),4326)::geography,v_session.corridor_meters) on conflict(session_id,location_id) do update set trigger_radius_meters=excluded.trigger_radius_meters,source='supabase_cache',discovered_at=now(),geofence_enabled=true; get diagnostics v_inserted=row_count; update public.route_discovery_sessions set status='ready',discovered_at=now(),updated_at=now() where id=p_session_id; return jsonb_build_object('session_id',p_session_id,'status','ready','locations_added',v_inserted); end; $$;

create or replace function public.prepare_route_discovery(p_route_id uuid, p_corridor_meters integer default 1000, p_expires_minutes integer default 180) returns public.route_discovery_sessions language plpgsql set search_path = public as $$ declare v_user uuid:=auth.uid(); v_route public.route_plans; v_session public.route_discovery_sessions; begin if v_user is null then raise exception 'Authentication required'; end if; select * into v_route from public.route_plans where id=p_route_id and user_id=v_user; if not found then raise exception 'Route not found'; end if; insert into public.route_discovery_sessions(user_id,route_id,origin_lat,origin_lng,destination_lat,destination_lng,corridor_meters,route_geometry,status,expires_at) values(v_user,p_route_id,v_route.start_lat,v_route.start_lng,v_route.end_lat,v_route.end_lng,greatest(100,p_corridor_meters),v_route.route_geometry,'planned',now()+make_interval(mins=>greatest(15,p_expires_minutes))) returning * into v_session; if v_route.route_geometry is not null then perform public.populate_route_discovery_cache(v_session.id,v_route.route_geometry); select * into v_session from public.route_discovery_sessions where id=v_session.id; end if; return v_session; end; $$;

create or replace function public.record_enterprise_partner_metric(p_network_id uuid, p_metric_date date, p_visits bigint default 0, p_check_ins bigint default 0, p_reviews bigint default 0, p_preferred_uses bigint default 0, p_access_redemptions bigint default 0, p_promotion_redemptions bigint default 0) returns public.enterprise_partner_network_metrics language plpgsql security definer set search_path = public, auth, extensions, pg_temp as $$ declare x public.enterprise_partner_network_metrics; begin if not exists(select 1 from public.enterprise_partner_networks n join public.businesses b on b.id=n.owner_business_id join public.business_members bm on bm.business_id=n.owner_business_id where n.id=p_network_id and bm.user_id=auth.uid() and bm.role in ('owner','admin') and lower(b.business_tier::text) in ('fleet','enterprise')) then raise exception 'network access denied'; end if; insert into public.enterprise_partner_network_metrics(network_id,metric_date,visits,check_ins,reviews,preferred_uses,access_redemptions,promotion_redemptions) values(p_network_id,p_metric_date,greatest(0,p_visits),greatest(0,p_check_ins),greatest(0,p_reviews),greatest(0,p_preferred_uses),greatest(0,p_access_redemptions),greatest(0,p_promotion_redemptions)) on conflict(network_id,metric_date) do update set visits=excluded.visits,check_ins=excluded.check_ins,reviews=excluded.reviews,preferred_uses=excluded.preferred_uses,access_redemptions=excluded.access_redemptions,promotion_redemptions=excluded.promotion_redemptions returning * into x; return x; end; $$;

create or replace function public.record_enterprise_partner_campaign_outcome(p_campaign_id uuid, p_partner_business_id uuid, p_visits bigint default 0, p_check_ins bigint default 0, p_reviews bigint default 0, p_preferred_uses bigint default 0, p_access_redemptions bigint default 0, p_promotion_redemptions bigint default 0, p_attributed_users bigint default 0, p_points_awarded bigint default 0) returns public.enterprise_partner_campaign_outcomes language plpgsql security definer set search_path = public, auth, extensions, pg_temp as $$ declare o public.enterprise_partner_campaign_outcomes; begin if not exists(select 1 from public.enterprise_partner_campaigns c join public.enterprise_partner_networks n on n.id=c.network_id join public.businesses b on b.id=n.owner_business_id join public.business_members bm on bm.business_id=n.owner_business_id where c.id=p_campaign_id and bm.user_id=auth.uid() and bm.role in ('owner','admin') and lower(b.business_tier::text) in ('fleet','enterprise')) then raise exception 'campaign access denied'; end if; if not exists(select 1 from public.enterprise_partner_network_members m where m.network_id=(select network_id from public.enterprise_partner_campaigns where id=p_campaign_id) and m.partner_business_id=p_partner_business_id and m.status='active') then raise exception 'partner is not active in network'; end if; insert into public.enterprise_partner_campaign_outcomes(campaign_id,partner_business_id,visits,check_ins,reviews,preferred_uses,access_redemptions,promotion_redemptions,attributed_users,points_awarded) values(p_campaign_id,p_partner_business_id,greatest(p_visits,0),greatest(p_check_ins,0),greatest(p_reviews,0),greatest(p_preferred_uses,0),greatest(p_access_redemptions,0),greatest(p_promotion_redemptions,0),greatest(p_attributed_users,0),greatest(p_points_awarded,0)) on conflict(campaign_id,partner_business_id,metric_date) do update set visits=excluded.visits,check_ins=excluded.check_ins,reviews=excluded.reviews,preferred_uses=excluded.preferred_uses,access_redemptions=excluded.access_redemptions,promotion_redemptions=excluded.promotion_redemptions,attributed_users=excluded.attributed_users,points_awarded=excluded.points_awarded returning * into o; return o; end; $$;

revoke execute on function public.record_favorite_route_event(uuid,uuid,numeric,numeric) from anon;
revoke execute on function public.record_location_route_event(uuid,boolean) from anon;
revoke execute on function public.populate_route_discovery_cache(uuid,jsonb) from anon;
revoke execute on function public.prepare_route_discovery(uuid,integer,integer) from anon;
revoke execute on function public.record_enterprise_partner_metric(uuid,date,bigint,bigint,bigint,bigint,bigint,bigint) from anon, authenticated;
grant execute on function public.record_enterprise_partner_metric(uuid,date,bigint,bigint,bigint,bigint,bigint,bigint) to authenticated;
revoke execute on function public.record_enterprise_partner_campaign_outcome(uuid,uuid,bigint,bigint,bigint,bigint,bigint,bigint,bigint,bigint) from anon, authenticated;
grant execute on function public.record_enterprise_partner_campaign_outcome(uuid,uuid,bigint,bigint,bigint,bigint,bigint,bigint,bigint,bigint) to authenticated;
